(function () {
  'use strict';

  const ACTIVE_CLASS = 'is-dragover';

  function acceptMatches(file, acceptAttr) {
    if (!acceptAttr) return true;
    const tokens = acceptAttr
      .split(',')
      .map((t) => t.trim().toLowerCase())
      .filter(Boolean);
    if (tokens.length === 0) return true;
    const name = (file.name || '').toLowerCase();
    const type = (file.type || '').toLowerCase();
    return tokens.some((token) => {
      if (token.startsWith('.')) return name.endsWith(token);
      if (token.endsWith('/*')) return type.startsWith(token.slice(0, -1));
      return type === token;
    });
  }

  function assignFiles(input, files) {
    if (!files || files.length === 0) return false;
    const filtered = Array.from(files).filter((f) => acceptMatches(f, input.accept));
    if (filtered.length === 0) return false;
    if (!input.multiple && filtered.length > 1) {
      filtered.length = 1;
    }
    try {
      const dt = new DataTransfer();
      filtered.forEach((f) => dt.items.add(f));
      input.files = dt.files;
    } catch (err) {
      return false;
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  }

  function initDropzone(zone, input) {
    if (!zone || !input || zone.dataset.dropzoneBound === '1') return;
    zone.dataset.dropzoneBound = '1';
    zone.classList.add('dropzone');

    let depth = 0;

    const onEnter = (e) => {
      if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;
      e.preventDefault();
      depth += 1;
      zone.classList.add(ACTIVE_CLASS);
    };
    const onOver = (e) => {
      if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'copy';
    };
    const onLeave = () => {
      depth = Math.max(0, depth - 1);
      if (depth === 0) zone.classList.remove(ACTIVE_CLASS);
    };
    const onDrop = (e) => {
      if (!e.dataTransfer || !e.dataTransfer.files || e.dataTransfer.files.length === 0) return;
      e.preventDefault();
      depth = 0;
      zone.classList.remove(ACTIVE_CLASS);
      assignFiles(input, e.dataTransfer.files);
    };
    const onPaste = (e) => {
      const files = e.clipboardData && e.clipboardData.files;
      if (!files || files.length === 0) return;
      if (assignFiles(input, files)) e.preventDefault();
    };

    zone.addEventListener('dragenter', onEnter);
    zone.addEventListener('dragover', onOver);
    zone.addEventListener('dragleave', onLeave);
    zone.addEventListener('drop', onDrop);
    zone.addEventListener('paste', onPaste);
    input.addEventListener('paste', onPaste);
  }

  function autoBind(root) {
    const scope = root || document;
    scope.querySelectorAll('[data-dropzone-for]').forEach((zone) => {
      const id = zone.getAttribute('data-dropzone-for');
      if (!id) return;
      const input = document.getElementById(id);
      if (input) initDropzone(zone, input);
    });
  }

  window.ClancalDropzone = { init: initDropzone, autoBind };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => autoBind());
  } else {
    autoBind();
  }
})();

