  --danger: #ef4444;
  --danger-light: #fee2e2;
  --info: #3b82f6;
  --info-light: #dbeafe;

  --dark: #1f2937;
  --gray-900: #111827;
  --gray-800: #1f2937;
  --gray-700: #374151;
  --gray-600: #4b5563;
  --gray-500: #6b7280;
  --gray-400: #9ca3af;
  --gray-300: #d1d5db;
  --gray-200: #E8E4E0;
  --gray-100: #F5F2EF;
  --gray-50: #FAF8F5;
  --white: #ffffff;

  /* Typography */
  --font-display: 'DM Serif Display', Georgia, serif;
  --font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(30, 20, 10, 0.05);
  --shadow: 0 1px 3px 0 rgba(30, 20, 10, 0.1), 0 1px 2px 0 rgba(30, 20, 10, 0.06);
  --shadow-md: 0 4px 6px -1px rgba(30, 20, 10, 0.1), 0 2px 4px -1px rgba(30, 20, 10, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(30, 20, 10, 0.1), 0 4px 6px -2px rgba(30, 20, 10, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(30, 20, 10, 0.1), 0 10px 10px -5px rgba(30, 20, 10, 0.04);

  /* Transitions */
  --transition-fast: 150ms ease-in-out;
  --transition-base: 200ms ease-in-out;
  --transition-slow: 300ms ease-in-out;

  /* Z-index */
  --z-dropdown: 1000;
  --z-sticky: 1020;
  --z-fixed: 1030;
  --z-modal-backdrop: 1040;
  --z-modal: 1050;
  --z-popover: 1060;
  --z-tooltip: 1070;

  /* Section Colors */
  --section-events: #0080FF;
  --section-trips: #0891B2;
  --section-recipes: #EA580C;
  --section-groceries: #16A34A;
  --section-households: #7C3AED;
  --section-feed: #EC4899;
  --gradient-warm: linear-gradient(135deg, #FF6600 0%, #FF8533 100%);
  --gradient-blue: linear-gradient(135deg, #0080FF 0%, #3399FF 100%);
  --gradient-festive: linear-gradient(135deg, #8B5CF6 0%, #A78BFA 100%);
}

/* ===================================
   Global Styles
   =================================== */

* {
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--gray-900);
  background-color: var(--gray-50);
  margin: 0;
  padding: 0;
  padding-top: 4rem;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  margin-top: 0;
  margin-bottom: var(--space-3);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.25;
  color: var(--gray-900);
}

h1 { font-size: var(--font-size-4xl); }
h2 { font-size: var(--font-size-3xl); }
h3 { font-size: var(--font-size-2xl); }
h4 { font-size: var(--font-size-xl); }
h5 { font-size: var(--font-size-lg); }
h6 { font-size: var(--font-size-base); }

p {
  margin-top: 0;
  margin-bottom: var(--space-4);
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--primary-hover);
}

/* ===================================
   Layout Components
   =================================== */

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.content-wrapper {
  min-height: calc(100vh - 8rem);
  padding: var(--space-8) 0;
}

/* ===================================
   Navigation - Bootstrap Overrides
   =================================== */

/* Navbar base styles */
.navbar {
  padding: 0;
  min-height: 4rem;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 2px solid transparent;
  border-image: linear-gradient(90deg, var(--primary), var(--secondary), var(--accent)) 1;
}

.navbar-brand {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: 400;
  color: var(--primary) !important;
}

.navbar-brand:hover {
  color: var(--primary-hover) !important;
}

/* Branded ClanCal logo in navbar */
.navbar-brand-logo {
  width: 32px;
  height: 32px;
  object-fit: contain;
}

/* Branded ClanCal logo on auth pages (login/signup) */
.auth-brand-logo {
  width: 48px;
  height: 48px;
  object-fit: contain;
}

/* Branded logo used as nav icon (for Events tab) */
.nav-icon-logo {
  width: 22px;
  height: 22px;
  object-fit: contain;
}

/* Slightly fade the nav logo when not active */
.navbar-nav .nav-link:not(.active) .nav-icon-logo {
  opacity: 0.7;
}

.navbar-nav .nav-link.active .nav-icon-logo,
.navbar-nav .nav-link:hover .nav-icon-logo {
  opacity: 1;
}

/* Container padding adjustment */
.navbar .container {
  padding: var(--space-3) var(--space-4);
}

/* Nav links styling */
.navbar-nav {
  gap: var(--space-2);
}

.navbar-nav .nav-item {
  margin: 0;
}

.navbar-nav .nav-link {
  color: var(--gray-700);
  font-weight: 500;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius);
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.navbar-nav .nav-link:hover {
  color: var(--primary);
  background-color: var(--primary-light);
}

.navbar-nav .nav-link.active {
  color: var(--primary);
  background-color: var(--primary-light);
}

/* Toggler button */
.navbar-toggler {
  padding: var(--space-1) var(--space-2);
  font-size: var(--font-size-lg);
}

.navbar-toggler:focus {
  box-shadow: none;
}

/* Collapse alignment */
@media (min-width: 992px) {
  .navbar-collapse {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
  }
}

/* User Menu */
.user-menu {
  position: relative;
}

.user-avatar {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius-full);
  object-fit: cover;
  border: 2px solid var(--gray-200);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.user-avatar:hover {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 128, 255, 0.15);
}

.avatar-placeholder {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius-full);
  background-color: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  font-size: var(--font-size-lg);
  transition: all var(--transition-fast);
}

.avatar-placeholder:hover {
  background-color: var(--primary-light);
  color: var(--primary);
}

/* Dropdown Menus */
.dropdown-menu {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: var(--space-2);
  background-color: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  min-width: 12rem;
  padding: var(--space-2);
  border: 1px solid var(--gray-100);
  display: none;
  z-index: var(--z-dropdown);
  transform: scale(0.95);
  opacity: 0;
  transition: transform var(--transition-fast), opacity var(--transition-fast);
}

.dropdown-menu.show {
  display: block;
  transform: scale(1);
  opacity: 1;
}

.dropdown-item {
  display: block;
  width: 100%;
  padding: var(--space-2) var(--space-3);
  color: var(--gray-700);
  border-radius: var(--radius);
  transition: all var(--transition-fast);
}

.dropdown-item:hover {
  background-color: var(--gray-50);
  color: var(--primary);
}

.dropdown-divider {
  height: 1px;
  margin: var(--space-2) 0;
  background-color: var(--gray-200);
  border: 0;
}

/* ===================================
   Cards
   =================================== */

.card {
  background-color: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow);
  padding: var(--space-6);
  margin-bottom: var(--space-6);
  border: 1px solid var(--gray-100);
  border-top: 3px solid transparent;
  transition: border-top-color var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  border-top-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.card-header {
  margin: calc(var(--space-6) * -1);
  margin-bottom: var(--space-6);
  padding: var(--space-4) var(--space-6);
  background-color: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
}

.card-title {
  margin-bottom: 0;
  font-size: var(--font-size-xl);
  font-weight: 600;
}

.card-body {
  padding: 0;
}

.card-footer {
  margin: var(--space-6) calc(var(--space-6) * -1) calc(var(--space-6) * -1);
  padding: var(--space-4) var(--space-6);
  background-color: var(--gray-50);
  border-top: 1px solid var(--gray-200);
  border-radius: 0 0 var(--radius-xl) var(--radius-xl);
}

/* ===================================
   Buttons
   =================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-base);
  font-weight: 500;
  line-height: 1.5;
  border-radius: var(--radius);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-decoration: none;
  white-space: nowrap;
  user-select: none;
  gap: var(--space-2);
}

.btn:hover {
  transform: scale(1.02) translateY(-1px);
  box-shadow: var(--shadow);
}

.btn:active {
  transform: scale(0.98);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(0, 128, 255, 0.3);
}

.btn-primary {
  background: var(--gradient-blue);
  color: var(--white);
  border-color: var(--primary);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
  color: var(--white);
}

.btn-primary:focus-visible {
  box-shadow: 0 0 0 3px rgba(0, 128, 255, 0.3);
}

.btn-secondary {
  background-color: var(--secondary);
  color: var(--white);
  border-color: var(--secondary);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
  border-color: var(--secondary-hover);
  color: var(--white);
}

.btn-secondary:focus-visible {
  box-shadow: 0 0 0 3px rgba(255, 102, 0, 0.3);
}

.btn-success {
  background-color: var(--success);
  color: var(--white);
  border-color: var(--success);
}

.btn-danger {
  background-color: var(--danger);
  color: var(--white);
  border-color: var(--danger);
}

.btn-outline-primary {
  background-color: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-outline-primary:hover {
  background-color: var(--primary);
  color: var(--white);
}

.btn-outline-secondary {
  background-color: transparent;
  color: var(--gray-600);
  border-color: var(--gray-300);
}

.btn-outline-secondary:hover {
  background-color: var(--gray-100);
  border-color: var(--gray-400);
  color: var(--gray-800);
}

.btn-sm {
  padding: var(--space-1) var(--space-3);
  font-size: var(--font-size-sm);
}

.btn-lg {
  padding: var(--space-3) var(--space-6);
  font-size: var(--font-size-lg);
}

.btn-icon {
  padding: var(--space-2);
  width: 2.5rem;
  height: 2.5rem;
}

/* ===================================
   Forms
   =================================== */

.form-group {
  margin-bottom: var(--space-4);
}

.form-label {
  display: block;
  font-weight: 500;
  color: var(--gray-700);
  margin-bottom: var(--space-2);
  font-size: var(--font-size-sm);
}

.form-control {
  display: block;
  width: 100%;
  padding: var(--space-2) var(--space-3);
  font-size: var(--font-size-base);
  line-height: 1.5;
  color: var(--gray-900);
  background-color: var(--white);
  border: 1px solid var(--gray-300);
  border-radius: var(--radius);
  transition: all var(--transition-fast);
}

.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 128, 255, 0.15);
}

.form-control::placeholder {
  color: var(--gray-400);
}

select.form-control {
  cursor: pointer;
}

textarea.form-control {
  min-height: 6rem;
  resize: vertical;
}

.form-check {
  display: flex;
  align-items: center;
  margin-bottom: var(--space-2);
}

.form-check-input {
  width: 1.25rem;
  height: 1.25rem;
  margin-right: var(--space-2);
  cursor: pointer;
}

.form-check-label {
  cursor: pointer;
  user-select: none;
}

.form-text {
  font-size: var(--font-size-sm);
  color: var(--gray-500);
  margin-top: var(--space-1);
}

.is-invalid {
  border-color: var(--danger);
}

.is-invalid:focus {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.1);
}

.invalid-feedback {
  font-size: var(--font-size-sm);
  color: var(--danger);
  margin-top: var(--space-1);
}

/* ===================================
   Alerts
   =================================== */

.alert-container {
  position: fixed;
  top: 5rem;
  right: var(--space-4);
  z-index: var(--z-popover);
  max-width: 24rem;
}

.alert {
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius);
  margin-bottom: var(--space-3);
  display: flex;
  align-items: center;
  justify-content: space-between;
  box-shadow: var(--shadow-md);
  animation: slideIn 0.3s ease-out;
}

@keyframes slideIn {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

.alert-success {
  background-color: var(--success-light);
  color: var(--gray-900);
  border-left: 4px solid var(--success);
}

.alert-danger {
  background-color: var(--danger-light);
  color: var(--gray-900);
  border-left: 4px solid var(--danger);
}

/* Map Django's 'error' tag to Bootstrap's 'danger' styling */
.alert-error {
  background-color: var(--danger-light);
  color: var(--gray-900);
  border-left: 4px solid var(--danger);
}

.alert-warning {
  background-color: var(--warning-light);
  color: var(--gray-900);
  border-left: 4px solid var(--warning);
}

.alert-info {
  background-color: var(--info-light);
  color: var(--gray-900);
  border-left: 4px solid var(--info);
}

.btn-close {
  background: none;
  border: none;
  font-size: var(--font-size-xl);
  line-height: 1;
  color: var(--gray-500);
  cursor: pointer;
  padding: 0;
  margin-left: var(--space-3);
}

/* ===================================
   Tables
   =================================== */

.table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--white);
}

.table th,
.table td {
  padding: var(--space-3) var(--space-4);
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.table th {
  font-weight: 600;
  color: var(--gray-700);
  background-color: var(--gray-50);
  font-size: var(--font-size-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.table tbody tr:hover {
  background-color: var(--gray-50);
}

.table-responsive {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/* ===================================
   Badges
   =================================== */

.badge {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-2);
  font-size: var(--font-size-xs);
  font-weight: 600;
  line-height: 1;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.badge-primary {
  background-color: var(--primary-light);
  color: var(--primary);
}

.badge-success {
  background-color: var(--success-light);
  color: var(--success);
}

.badge-warning {
  background-color: var(--warning-light);
  color: var(--warning);
}

.badge-danger {
  background-color: var(--danger-light);
  color: var(--danger);
}

.badge-info {
  background-color: var(--info-light);
  color: var(--info);
}

/* ===================================
   Notifications
   =================================== */

.notification-badge {
  position: absolute;
  top: -0.25rem;
  right: -0.25rem;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 var(--space-1);
  background-color: var(--danger);
  color: var(--white);
  font-size: var(--font-size-xs);
  font-weight: 600;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
}

.notification-dropdown {
  width: 20rem;
  max-height: 25rem;
  overflow: hidden;
  padding: 0;
  margin-top: var(--space-2);
}

.notification-header {
  padding: var(--space-3) var(--space-4);
  background-color: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
  font-weight: 600;
}

.notification-list {
  max-height: 18rem;
  overflow-y: auto;
}

.notification-item {
  display: flex;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--gray-100);
  transition: background-color var(--transition-fast);
  cursor: pointer;
  text-decoration: none;
  color: inherit;
}

.notification-item:hover {
  background-color: var(--gray-50);
  text-decoration: none;
  color: inherit;
}

.notification-item.unread {
  background-color: var(--primary-light);
}

.notification-title {
  font-weight: 600;
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-1);
  color: var(--gray-900);
}

.notification-text {
  font-size: var(--font-size-sm);
  color: var(--gray-600);
  margin-bottom: var(--space-1);
}

.notification-time {
  font-size: var(--font-size-xs);
  color: var(--gray-400);
}

/* Notification badge bounce animation */
@keyframes badgeBounce {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.3); }
}
.badge-bounce { animation: badgeBounce 0.3s ease-in-out 2; }

/* Notification type left-border color coding */
.notification-type-event { border-left: 4px solid var(--info) !important; }
.notification-type-task { border-left: 4px solid var(--warning) !important; }
.notification-type-system { border-left: 4px solid var(--gray-400) !important; }
.notification-type-user-action { border-left: 4px solid var(--success) !important; }
.notification-type-network-invite { border-left: 4px solid #8b5cf6 !important; }

/* ===================================
   Footer
   =================================== */

.footer {
  background-color: #1C1917;
  border-top: none;
  padding: var(--space-8) 0;
  margin-top: var(--space-16);
  color: rgba(255, 255, 255, 0.7);
}

.footer-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-content p {
  color: rgba(255, 255, 255, 0.7);
}

.footer-links {
  display: flex;
  gap: var(--space-6);
}

.footer-links a {
  color: rgba(255, 255, 255, 0.6);
  font-size: var(--font-size-sm);
}

.footer-links a:hover {
  color: var(--white);
}

/* ===================================
   Utilities
   =================================== */

.text-center { text-align: center; }
.text-right { text-align: right; }
.text-muted { color: var(--gray-500); }
.text-small { font-size: var(--font-size-sm); }

.mt-1 { margin-top: var(--space-1); }
.mt-2 { margin-top: var(--space-2); }
.mt-3 { margin-top: var(--space-3); }
.mt-4 { margin-top: var(--space-4); }
.mt-6 { margin-top: var(--space-6); }
.mt-8 { margin-top: var(--space-8); }

.mb-1 { margin-bottom: var(--space-1); }
.mb-2 { margin-bottom: var(--space-2); }
.mb-3 { margin-bottom: var(--space-3); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }

.p-0 { padding: 0; }
.p-2 { padding: var(--space-2); }
.p-4 { padding: var(--space-4); }
.p-6 { padding: var(--space-6); }

.d-flex { display: flex; }
.align-items-center { align-items: center; }
.justify-content-between { justify-content: space-between; }
.justify-content-center { justify-content: center; }
.flex-wrap { flex-wrap: wrap; }
.gap-2 { gap: var(--space-2); }
.gap-4 { gap: var(--space-4); }

.w-100 { width: 100%; }
.h-100 { height: 100%; }

/* ===================================
   Collapse Component
   =================================== */

.collapse {
  display: none;
}

.collapse.show {
  display: block;
}

.collapsing {
  height: 0;
  overflow: hidden;
  transition: height 0.35s ease;
}

/* ===================================
   Quick Actions Buttons
   =================================== */

/* Ensure all Quick Actions buttons have visible borders */
.card-header + .card-body a.btn[class*="btn-outline"],
[class*="Quick Actions"] ~ .card-body a.btn[class*="btn-outline"],
.card h5:contains("Quick Actions") ~ .card-body a.btn {
  border-width: 1px !important;
  border-style: solid !important;
}

/* Specific border colors for different button variants */
.card-body a.btn.btn-outline-primary {
  border-color: var(--bs-primary, #0d6efd) !important;
}

.card-body a.btn.btn-outline-secondary {
  border-color: var(--bs-secondary, #6c757d) !important;
}

.card-body a.btn.btn-outline-success {
  border-color: var(--bs-success, #198754) !important;
}

.card-body a.btn.btn-outline-info {
  border-color: var(--bs-info, #0dcaf0) !important;
}

.card-body a.btn.btn-outline-warning {
  border-color: var(--bs-warning, #ffc107) !important;
}

.card-body a.btn.btn-outline-danger {
  border-color: var(--bs-danger, #dc3545) !important;
}

/* Ensure primary buttons also have borders */
.card-body a.btn.btn-primary {
  border: 1px solid var(--bs-primary, #0d6efd) !important;
}

/* ===================================
   Party/Social Event Styling
   =================================== */

/* Party theme colors */
:root {
  --party-primary: #8B5CF6;
  --party-secondary: #A78BFA;
  --party-light: #F5F3FF;
  --party-badge: #7C3AED;
  --party-gradient: linear-gradient(135deg, #8B5CF6 0%, #A78BFA 50%, #C4B5FD 100%);
}

/* Party event card styling */
.event-card--party {
  border-left: 4px solid var(--party-primary);
  background: linear-gradient(to right, var(--party-light) 0%, var(--white) 100%);
}

.event-card--party:hover {
  border-left-color: var(--party-badge);
  box-shadow: 0 4px 12px rgba(139, 92, 246, 0.15);
}

/* Party badge styling */
.event-badge--party,
.badge-party {
  background-color: var(--party-primary);
  color: var(--white);
}

.badge-party-light {
  background-color: var(--party-light);
  color: var(--party-primary);
}

/* Party header for event detail */
.party-header {
  background: var(--party-gradient);
  color: var(--white);
  padding: var(--space-6);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  margin: calc(var(--space-6) * -1);
  margin-bottom: var(--space-6);
  position: relative;
  overflow: hidden;
}

.party-header::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
  animation: partyPulse 4s ease-in-out infinite;
}

@keyframes partyPulse {
  0%, 100% { transform: scale(1); opacity: 0.5; }
  50% { transform: scale(1.1); opacity: 0.3; }
}

.party-header h1,
.party-header h2,
.party-header h3 {
  color: var(--white);
  position: relative;
  z-index: 1;
}

.party-header .text-muted {
  color: rgba(255, 255, 255, 0.85) !important;
}

/* Party event type indicator */
.event-type-indicator--party {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-2);
  background-color: var(--party-light);
  color: var(--party-primary);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
}

.event-type-indicator--party i {
  font-size: 0.9em;
}

/* Party invite button */
.btn-party {
  background-color: var(--party-primary);
  color: var(--white);
  border-color: var(--party-primary);
}

.btn-party:hover {
  background-color: var(--party-badge);
  border-color: var(--party-badge);
  color: var(--white);
}

.btn-outline-party {
  background-color: transparent;
  color: var(--party-primary);
  border-color: var(--party-primary);
}

.btn-outline-party:hover {
  background-color: var(--party-primary);
  color: var(--white);
}

/* Invitation status badges */
.badge-accepted,
.bg-accepted {
  background-color: var(--success-light);
  color: #059669;
}

.badge-pending,
.bg-pending {
  background-color: var(--warning-light);
  color: #D97706;
}

.badge-declined,
.bg-declined {
  background-color: var(--danger-light);
  color: #DC2626;
}

.badge-expired,
.bg-expired {
  background-color: var(--gray-200);
  color: var(--gray-600);
}

.badge-revoked,
.bg-revoked {
  background-color: var(--gray-200);
  color: var(--gray-500);
}

/* Invitation list styling */
.invitation-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-3);
  background-color: var(--gray-50);
  border-radius: var(--radius);
  margin-bottom: var(--space-2);
  transition: all var(--transition-fast);
}

.invitation-item:hover {
  background-color: var(--gray-100);
}

.invitation-item:last-child {
  margin-bottom: 0;
}

.invitation-email {
  font-weight: 500;
  color: var(--gray-800);
}

.invitation-details {
  font-size: var(--font-size-sm);
  color: var(--gray-500);
}

.invitation-actions {
  display: flex;
  gap: var(--space-2);
}

/* Guest RSVP details */
.guest-rsvp-info {
  padding: var(--space-2) var(--space-3);
  background-color: var(--gray-50);
  border-radius: var(--radius);
  margin-top: var(--space-2);
  font-size: var(--font-size-sm);
}

.guest-rsvp-info .plus-one {
  color: var(--party-primary);
  font-weight: 500;
}

.guest-rsvp-info .dietary {
  color: var(--warning);
}

/* ===================================
   Animations & Interactions
   =================================== */

@keyframes fadeSlideUp {
    from { opacity: 0; transform: translateY(16px); }
    to { opacity: 1; transform: translateY(0); }
}

.household-card, .grocery-card, .event-card, .recipe-card, .post-card {
    animation: fadeSlideUp 0.4s ease-out both;
}
.household-card:nth-child(2), .grocery-card:nth-child(2), .recipe-card:nth-child(2) { animation-delay: 0.08s; }
.household-card:nth-child(3), .grocery-card:nth-child(3), .recipe-card:nth-child(3) { animation-delay: 0.16s; }
.household-card:nth-child(4), .grocery-card:nth-child(4), .recipe-card:nth-child(4) { animation-delay: 0.24s; }
.household-card:nth-child(5), .grocery-card:nth-child(5), .recipe-card:nth-child(5) { animation-delay: 0.32s; }
.household-card:nth-child(6), .grocery-card:nth-child(6), .recipe-card:nth-child(6) { animation-delay: 0.40s; }

/* Progress bar animation */
@keyframes progressFill {
    from { width: 0; }
}

.grocery-progress-bar .fill,
.progress-bar-large .progress-fill {
    animation: progressFill 0.8s ease-out;
}

/* Badge hover pulse */
.badge:hover {
    animation: subtlePulse 0.3s ease;
}

@keyframes subtlePulse {
    50% { transform: scale(1.05); }
}

/* Form focus smooth transition */
.form-control, .form-select {
    transition: border-color var(--transition-base), box-shadow var(--transition-base);
}

/* Enhanced alert entrance */
@keyframes slideInBounce {
    0% { transform: translateX(120%); opacity: 0; }
    60% { transform: translateX(-5%); opacity: 1; }
    100% { transform: translateX(0); opacity: 1; }
}

.alert {
    animation: slideInBounce 0.4s ease-out;
}

/* Enhanced Empty States — only the standalone decorative icon, not icons inside buttons */
.empty-state > i,
.no-events > i,
.empty-items > i {
    color: var(--primary);
    opacity: 0.4;
}

/* ===================================
   Responsive Design
   =================================== */

@media (max-width: 991px) {
  .navbar-collapse {
    position: fixed;
    top: 4rem;
    left: 0;
    right: 0;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(12px);
    box-shadow: var(--shadow);
    padding: var(--space-4);
    border-top: 1px solid var(--gray-200);
  }

  .navbar-nav {
    flex-direction: column;
    width: 100%;
    gap: var(--space-1);
  }

  .navbar-nav .nav-item {
    width: 100%;
  }

  .navbar-nav .nav-link {
    width: 100%;
    justify-content: flex-start;
  }
}

@media (max-width: 768px) {

  .container {
    padding: 0 var(--space-3);
  }

  .card {
    padding: var(--space-4);
  }

  .footer-content {
    flex-direction: column;
    text-align: center;
  }

  .footer-links {
    flex-direction: column;
    gap: var(--space-2);
  }

  .dropdown-menu {
    position: static;
    width: 100%;
    box-shadow: none;
    border: none;
    background-color: var(--gray-50);
    margin-top: 0;
  }
}
