{% extends "base.html" %}
{% load static %}

{% block title %}Photos - {{ trip.name }}{% endblock %}

{% block extra_css %}
<style>
    .photo-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--space-3);
    }

    .photo-card {
        position: relative;
        border-radius: var(--radius-md);
        overflow: hidden;
        aspect-ratio: 1;
        background: var(--gray-100);
    }

    .photo-card img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    .photo-card video {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    .photo-card .photo-overlay {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        background: linear-gradient(transparent, rgba(0,0,0,0.7));
        color: white;
        padding: var(--space-2) var(--space-3);
        font-size: var(--font-size-sm);
    }

    .photo-card .photo-source-badge {
        position: absolute;
        top: var(--space-2);
        left: var(--space-2);
        font-size: var(--font-size-xs);
    }

    .photo-card .photo-delete-btn {
        position: absolute;
        top: var(--space-2);
        right: var(--space-2);
    }

    .upload-section {
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-4);
        margin-bottom: var(--space-4);
    }
</style>
{% endblock %}

{% block content %}
<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="{% url 'trips:trip_list' %}">Trips</a></li>
            <li class="breadcrumb-item"><a href="{% url 'trips:trip_detail' pk=trip.pk %}">{{ trip.name }}</a></li>
            <li class="breadcrumb-item active" aria-current="page">Photos</li>
        </ol>
    </nav>

    <div class="d-flex justify-content-between align-items-center mb-4">
        <h2>Photos ({{ photo_count }})</h2>
    </div>

    <!-- Upload Section -->
    <div class="upload-section">
        <h5 class="mb-3">Upload Photos</h5>
        <form method="post" action="{% url 'trips:trip_photo_upload' trip_pk=trip.pk %}" enctype="multipart/form-data">
            {% csrf_token %}
            <div class="d-flex gap-3 align-items-end">
                <div class="flex-grow-1">
                    <input type="file" name="photos" class="form-control" multiple accept="image/*,video/*">
                </div>
                <button type="submit" class="btn btn-primary">
                    <i class="bi bi-upload me-1"></i>Upload
                </button>
            </div>
        </form>
    </div>

    <!-- Photo Grid -->
    {% if photos %}
    <div class="photo-grid">
        {% for photo in photos %}
        <div class="photo-card">
            {% if photo.file_url %}
                {% if photo.media_type == "VIDEO" %}
            <video
                src="{{ photo.file_url }}"
                {% if photo.thumbnail_url %}poster="{{ photo.thumbnail_url }}"{% endif %}
                controls
                preload="metadata"
                playsinline
            ></video>
                {% else %}
            <img src="{{ photo.file_url }}" alt="{{ photo.caption|default:'Trip photo' }}" loading="lazy">
                {% endif %}
            {% endif %}

            <span class="photo-source-badge badge bg-{% if photo.source == 'trip' %}primary{% else %}info{% endif %}">
                {% if photo.source == "event" %}{{ photo.event_title|truncatechars:20 }}{% else %}Trip{% endif %}
            </span>

            {% if photo.can_delete %}
            <form method="post" action="{% url 'trips:trip_photo_delete' trip_pk=trip.pk pk=photo.id %}" class="photo-delete-btn">
                {% csrf_token %}
                <button type="submit" class="btn btn-sm btn-danger" onclick="return confirm('Delete this photo?')" title="Delete">
                    <i class="bi bi-trash"></i>
                </button>
            </form>
            {% endif %}

            <div class="photo-overlay">
                <div>{{ photo.uploaded_by_name }}</div>
                {% if photo.caption %}<div class="text-truncate">{{ photo.caption }}</div>{% endif %}
            </div>
        </div>
        {% endfor %}
    </div>
    {% else %}
    <div class="text-center py-5 text-muted">
        <i class="bi bi-camera" style="font-size: 2rem; opacity: 0.3;"></i>
        <p class="mt-2">No photos yet — add the first one!</p>
    </div>
    {% endif %}
</div>
{% endblock %}

