{% block content %}
<div class="container">
    <a href="{% url 'trips:grocery_list_list' trip_pk=trip.pk %}" class="back-link">
        <i class="bi bi-arrow-left"></i>Back to Grocery Lists
    </a>

    <div class="list-header">
        <div>
            <h1><i class="bi bi-cart me-2"></i>{{ grocery_list.name }}</h1>
            {% if grocery_list.description %}
            <p class="text-muted">{{ grocery_list.description }}</p>
            {% endif %}
        </div>
        <div class="list-actions">
            <a href="{% url 'trips:coupon_suggestions' trip_pk=trip.pk pk=grocery_list.pk %}" class="btn btn-primary">
                <i class="bi bi-camera me-1"></i>Scan Coupons
            </a>
            <a href="{% url 'trips:grocery_list_edit' trip_pk=trip.pk pk=grocery_list.pk %}" class="btn btn-outline-secondary">
                <i class="bi bi-pencil me-1"></i>Edit
            </a>
            <a href="{% url 'trips:grocery_list_delete' trip_pk=trip.pk pk=grocery_list.pk %}" class="btn btn-outline-danger">
                <i class="bi bi-trash me-1"></i>Delete
            </a>
        </div>
    </div>

    <!-- Progress Section -->
    <div class="progress-section">
        <div class="progress-header">
            <h3 class="mb-0">Progress</h3>
            <div class="progress-stats">
                {{ grocery_list.items.filter.is_completed|length|default:0 }} of {{ items.count }} items purchased
            </div>
        </div>
        <div class="progress-bar-large">
            <div class="progress-fill" style="width: {{ grocery_list.completion_percentage }}%"></div>
        </div>
    </div>

    <!-- Items Section -->
    <div class="items-section">
        <div class="items-header">
            <h2>Items ({{ items.count }})</h2>
        </div>

        {% if items %}
            {% regroup items by category as items_by_category %}
            {% for category_group in items_by_category %}
            <div class="category-group">
                <div class="category-header">
                    {% if category_group.grouper %}
                        {{ category_group.grouper.name }}
                    {% else %}
                        Uncategorized
                    {% endif %}
                </div>
                {% for item in category_group.list %}
                <div class="item-row">
                    <form method="post" action="{% url 'trips:grocery_item_toggle' trip_pk=trip.pk list_pk=grocery_list.pk pk=item.pk %}" style="display: inline;">
                        {% csrf_token %}
                        <input type="checkbox"
                               class="item-checkbox"
                               {% if item.is_completed %}checked{% endif %}
                               onchange="this.form.submit()">
                    </form>
                    <div class="item-info">
                        <div class="item-name {% if item.is_completed %}completed{% endif %}">
                            {{ item.name }}
                        </div>
                        <div class="item-meta">
                            {% if item.description %}{{ item.description }} | {% endif %}
                            {% if item.assigned_to %}Assigned to: {{ item.assigned_to.get_full_name|default:item.assigned_to.username }}{% endif %}
                        </div>
                    </div>
                    <span class="item-quantity">{{ item.quantity }} {{ item.get_unit_display }}</span>
                    <div class="item-actions">
                        <form method="post" action="{% url 'trips:grocery_item_delete' trip_pk=trip.pk list_pk=grocery_list.pk pk=item.pk %}" style="display: inline;">
                            {% csrf_token %}
                            <button type="submit" class="btn-icon" title="Delete" onclick="return confirm('Delete this item?')">
                                <i class="bi bi-trash"></i>
                            </button>
                        </form>
                    </div>
                </div>
                {% endfor %}
            </div>
            {% endfor %}
        {% else %}
            <div class="empty-items">
                <i class="bi bi-cart"></i>
                <p>No items in this list yet</p>
            </div>
        {% endif %}

        <!-- Add Item Form -->
        <div class="add-item-form">
            <h4 class="mb-3">Add Item</h4>
            <form method="post">
                {% csrf_token %}
                <div class="add-item-row">
                    <div class="form-group">
                        <label class="form-label">Item Name</label>
                        <input type="text" name="name" class="form-control" required placeholder="e.g., Milk">
                    </div>
                    <div class="form-group" style="flex: 0 0 80px;">
                        <label class="form-label">Quantity</label>
                        <input type="number" name="quantity" class="form-control" value="1" min="1">
                    </div>
                    <div class="form-group" style="flex: 0 0 100px;">
                        <label class="form-label">Unit</label>
                        <select name="unit" class="form-select">
                            {% for value, label in item_form.fields.unit.choices %}
                                <option value="{{ value }}">{{ label }}</option>
                            {% endfor %}
                        </select>
                    </div>
                    <div class="form-group" style="flex: 0 0 150px;">
                        <label class="form-label">Category</label>
                        <select name="category" class="form-select">
                            <option value="">Uncategorized</option>
                            {% for category in item_form.fields.category.queryset %}
                                <option value="{{ category.pk }}">{{ category.name }}</option>
                            {% endfor %}
                        </select>
                    </div>
                    <div class="form-group" style="flex: 0 0 auto;">
                        <button type="submit" name="add_item" class="btn btn-primary">
                            <i class="bi bi-plus-lg me-1"></i>Add
                        </button>
                    </div>
                </div>
            </form>
        </div>
    </div>
</div>
{% endblock %}
