<script>
// Drag and drop handling
const uploadZone = document.getElementById('uploadZone');
const mediaInput = document.getElementById('mediaInput');

['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
    uploadZone.addEventListener(eventName, preventDefaults, false);
});

function preventDefaults(e) {
    e.preventDefault();
    e.stopPropagation();
}

['dragenter', 'dragover'].forEach(eventName => {
    uploadZone.addEventListener(eventName, () => uploadZone.classList.add('dragover'));
});

['dragleave', 'drop'].forEach(eventName => {
    uploadZone.addEventListener(eventName, () => uploadZone.classList.remove('dragover'));
});

uploadZone.addEventListener('drop', (e) => {
    const dt = e.dataTransfer;
    const files = dt.files;
    handleFiles(files);
});

uploadZone.addEventListener('click', () => mediaInput.click());

let selectedFiles = [];

function previewMedia(input) {
    handleFiles(input.files);
}

function handleFiles(files) {
    const preview = document.getElementById('mediaPreview');

    [...files].forEach(file => {
        if (!file.type.startsWith('image/') && !file.type.startsWith('video/')) return;

        selectedFiles.push(file);
        const index = selectedFiles.length - 1;

        const div = document.createElement('div');
        div.className = 'media-preview-item';
        div.dataset.index = index;

        if (file.type.startsWith('image/')) {
            const img = document.createElement('img');
            img.src = URL.createObjectURL(file);
            div.appendChild(img);
        } else {
            const video = document.createElement('video');
            video.src = URL.createObjectURL(file);
            div.appendChild(video);
        }

        const removeBtn = document.createElement('button');
        removeBtn.className = 'media-preview-remove';
        removeBtn.innerHTML = '<i class="bi bi-x"></i>';
        removeBtn.onclick = () => removeMedia(index);
        div.appendChild(removeBtn);

        preview.appendChild(div);
    });
}

function removeMedia(index) {
    selectedFiles[index] = null;
    document.querySelector(`.media-preview-item[data-index="${index}"]`).remove();
}

// Form submission
document.getElementById('createPostForm').addEventListener('submit', async (e) => {
    e.preventDefault();

    const content = document.getElementById('postContent').value;
    const familyCheckboxes = document.querySelectorAll('input[name="family_ids"]:checked');
    const familyIds = [...familyCheckboxes].map(cb => cb.value);

    if (!content && selectedFiles.filter(f => f).length === 0) {
        alert('Please add some content or media to your post.');
        return;
    }

    if (familyIds.length === 0) {
        alert('Please select at least one family to share with.');
        return;
    }

    try {
        // Create the post first
        const postResponse = await fetch('/api/famstream/', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': document.querySelector('[name=csrfmiddlewaretoken]').value
            },
            body: JSON.stringify({
                content: content,
                family_ids: familyIds
            })
        });

        if (!postResponse.ok) {
            throw new Error('Failed to create post');
        }

        const post = await postResponse.json();

        // Upload media if any
        const filesToUpload = selectedFiles.filter(f => f);
        for (let i = 0; i < filesToUpload.length; i++) {
            const formData = new FormData();
            formData.append('file', filesToUpload[i]);
            formData.append('order', i);

            await fetch(`/api/famstream/${post.id}/media/`, {
                method: 'POST',
                headers: {
                    'X-CSRFToken': document.querySelector('[name=csrfmiddlewaretoken]').value
                },
                body: formData
            });
        }

        // Reload to show new post
        location.reload();

    } catch (err) {
        console.error('Failed to create post:', err);
        alert('Failed to create post. Please try again.');
    }
});
</script>
